StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME: 	   HE_FrekvOmf_Vacon100_Wrapper                                                                                                                                                                                                                                                                     
//	CREATOR:	   William Veim                                                                                                                                                                                                                                               
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//  1.0.0				20.01.2025		William Veim			Initial release
//  1.1.0				27.01.2026		William Veim			Updated according to field testing

//===============================================================================================================================
//
//		DESCRIPTION:
//
//		FUNCTION:
//
//
//===============================================================================================================================

(*************************************************************************
 *	Update Inputs
 *************************************************************************)

// Config Parameter
Ext_VFD.EXT_Engineering.Auto_Visible:= 							Cfg_Auto_InUse;
Ext_VFD.EXT_General.LocationIndex[0]:=							Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_VFD.EXT_Engineering.ReverseRunning_Visible:=			TRUE;
Ext_VFD.EXT_Engineering.LCfg_Autotune_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_MotorData_Visible:=			FALSE;
Ext_VFD.EXT_Engineering.LCfg_RampTime_Visible:=			FALSE;

// Input Parmeter
//------------------
FB_VFD_Logic.Cfg_ControllerTAG:=				Cfg_ControllerName;
FB_VFD_Logic.Cfg_ProcessTAG:=					Cfg_ProcessTAG;
FB_VFD_Logic.Inp_AutoRunFwd :=				Inp_AutoStartRef;
FB_VFD_Logic.Inp_AutoSpeedRef :=			Inp_AutoSpeedRef;
FB_VFD_Logic.Inp_LOTO:=							Inp_LOTO;
FB_VFD_Logic.Cfg_LOTO_InUse	:=				Cfg_LOTO_InUse;
FB_VFD_Logic.Inp_Interlock:=						Inp_Interlock;
FB_VFD_Logic.Cfg_Interlock_InUse:=			Cfg_Interlock_InUse;
FB_VFD_Logic.Cfg_STO_InUse:=					Cfg_STO_InUse;
FB_VFD_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_VFD_Logic.Inp_AlmSuppressDesc:= 		Inp_AlmSuppressDesc;
FB_VFD_Logic.Inp_ComFault :=					HE_CommFault(PORT:=Cfg_EIP_Interface, IP:=Cfg_DriveIP);

// Feltbuss Input
//------------------
FB_VFD_Logic.Inp_STO:=	 							FALSE; //Not available
FB_VFD_Logic.Inp_Remote :=						Ext_VFD_Input.FBProcessDataOut2.Bit[7]; //Fieldbus control active
FB_VFD_Logic.Inp_Ready := 						Ext_VFD_Input.FB_FixedStatusWrd.Bit[0]; //Drive ready
FB_VFD_Logic.Inp_RunningFwd := 				Ext_VFD_Input.FB_FixedStatusWrd.Bit[1] AND NOT Ext_VFD_Input.FB_FixedStatusWrd.Bit[2]; //Started and not reverse running
FB_VFD_Logic.Inp_RunningRev :=				Ext_VFD_Input.FB_FixedStatusWrd.Bit[2]; //Reverse
FB_VFD_Logic.Inp_Error  := 							Ext_VFD_Input.FB_FixedStatusWrd.Bit[3]; //Fault is active
FB_VFD_Logic.Inp_Warning := 					Ext_VFD_Input.FB_FixedStatusWrd.Bit[4]; //Warning is active
FB_VFD_Logic.Inp_VoltageEnabled := 			Ext_VFD_Input.FBProcessDataOut1.Bit[4]; //Voltage enabled
FB_VFD_Logic.Inp_LocalStop := 					Ext_VFD_Input.FBProcessDataOut2.Bit[15]; //Stopped from keypad
FB_VFD_Logic.Inp_Online :=						Ext_VFD_Input.FBProcessDataOut1.Bit[2] //Charge switch closed
																	AND Ext_VFD_Input.FBProcessDataOut1.Bit[4] //Power Unit OK
																	AND Ext_VFD_Input.FBProcessDataOut1.Bit[5] //Start allowed (Power unit)
																	AND Ext_VFD_Input.FBProcessDataOut1.Bit[6]; //Start allowed (System software)

FB_VFD_Logic.Inp_ActSpeed := ScaleTrans(SclIn:=INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.FBSpeedActual.Wrd)),
																	  	X0:=REAL#0.0,
																	  	Y0:=REAL#0.0,
																	  	X1:=REAL#10000.0,
																	  	Y1:=REAL#100.0);

(*************************************************************************
 *	VFD Power, Current, Energy
 *************************************************************************)
 
FB_VFD_Logic.Inp_Power :=  	INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.FBProcessDataOut3.Wrd))/10;
FB_VFD_Logic.Inp_Current :=	INT_TO_REAL(WORD_TO_INT(Ext_VFD_Input.FBProcessDataOut4.Wrd)) /10;
FB_VFD_Logic.Inp_Energy := 	WORD_TO_REAL(Ext_VFD_Input.FBProcessDataOut5.Wrd)+(WORD_TO_REAL(Ext_VFD_Input.FBProcessDataOut6.Wrd)*65535);

	
(*************************************************************************
 *	Runtime Statistics
 *************************************************************************)

FB_VFD_Logic.Inp_VFD_TotalRunTime:= ((WORD_TO_ULINT(Ext_VFD_Input.FBProcessDataOut10.Wrd) * 8765) + (WORD_TO_ULINT(Ext_VFD_Input.FBProcessDataOut11.Wrd) * 24));
FB_VFD_Logic.Inp_VFD_TotalOnTime:=  ((WORD_TO_ULINT(Ext_VFD_Input.FBProcessDataOut12.Wrd) * 8765) + (WORD_TO_ULINT(Ext_VFD_Input.FBProcessDataOut13.Wrd) * 24));
	
(*************************************************************************
 *	State and error
 *************************************************************************)
	
FB_VFD_Logic.Inp_Active_Error:= 		HE_100F_Drive_Fault(Inp_LastFault:=Ext_VFD_Input.FBProcessDataOut7.Wrd, Cfg_Delimiter:=' - ', Cfg_Composition:=7); //Same parsing for error and warning
FB_VFD_Logic.Inp_Active_Warning:= 	HE_100F_Drive_Fault(Inp_LastFault:=Ext_VFD_Input.FBProcessDataOut8.Wrd, Cfg_Delimiter:=' - ', Cfg_Composition:=7); //Same parsing for error and warning
FB_VFD_Logic.Inp_Actual_State:=		HE_100F_Drive_State(Inp_State:=Ext_VFD_Input.FB_FixedStatusWrd.Wrd, Cfg_Delimiter:=' - ', Cfg_Composition:= 7);
	
(*************************************************************************
 *	Execute VFD Logic
 *************************************************************************)
 
FB_VFD_Logic(Ext_VFD:=Ext_VFD, 
							Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	Reset VFD communiation error after CPU startup
 *************************************************************************)

TOF_CPUStartup(In:=P_First_Run, PT:=TIME#10s);

Wrk_ResetCommFault:= FB_VFD_Logic.Inp_Active_Error = '53 - Fieldbus communication fault' AND TOF_CPUStartup.Q;

(*************************************************************************
 *	Update VFD Output
 *************************************************************************)

Sts_Alarm:=					FB_VFD_Logic.Sts_AlarmTriggered;
Sts_AvailableAuto:=		FB_VFD_Logic.Sts_AvailableAuto;
Sts_Interlock := 			FB_VFD_Logic.Sts_Interlock;
Sts_RunningFwd := 		FB_VFD_Logic.Inp_RunningFwd;

// Ethernet/IP Output
//----------------------
Ext_VFD_Output.FBFixedControlWord.Bit[0] :=FB_VFD_Logic.Out_Enable AND (FB_VFD_Logic.Out_RunFwd OR FB_VFD_Logic.Out_RunRev); //Start running
Ext_VFD_Output.FBFixedControlWord.Bit[1] :=FB_VFD_Logic.Out_RunRev; //Start running rev
Ext_VFD_Output.FBFixedControlWord.Bit[2]:= FB_VFD_Logic.Out_FaultReset OR Wrk_ResetCommFault; //Reset fault
Ext_VFD_Output.FBSpeedReference.Wrd:=     INT_TO_WORD(REAL_TO_INT(ScaleTrans(SclIn:=FB_VFD_Logic.Out_SpeedRef,
																																		X0:=0.0,
																																		Y0:=0.0,
																																		X1:=100.0,
																																		Y1:=10000.0)));
